import itertools

def calculate_Q(x, y, z, a, b, c):
    return abs(x + y - a - b) + abs(y + z - b - c) + abs(z + x - c - a)

# Q1 = Q(x, y, z; 0, 0, 0) => 2*(x+y+z)
# Q2 = Q(x, y, z; 0, 1, 0)
Q1_a, Q1_b, Q1_c = 0, 0, 0
Q2_a, Q2_b, Q2_c = 0, 1, 0

collision_count = 0
mapping = {}
count = 0

for x in range(10):
    for y in range(10):
        for z in range(10):
            count += 1

            # Calculate the pair of measurement values
            q1 = calculate_Q(x, y, z, Q1_a, Q1_b, Q1_c)
            q2 = calculate_Q(x, y, z, Q2_a, Q2_b, Q2_c)

            key = (q1, q2)

            if key in mapping:
                collision_count += 1
            else:
                mapping[key] = [x, y, z]

            if collision_count > 0:
                # Stop early once ambiguity is found
                print(f"Collision found at triple {count}:")
                print(f"Key: {key}")
                print(f"Original triple: {mapping[key]}")
                # This print statement is just for verification; we rely on collision_count
                pass

print(f"Total triples checked: {count}")
print(f"Number of collision pairs found: {collision_count}")

if collision_count == 0:
    print("Conclusion: (Q1, Q2) is sufficient to uniquely determine (x, y, z).")
else:
    print("Conclusion: (Q1, Q2) is NOT sufficient to uniquely determine (x, y, z).")
